-- Newsroom drafts for 2026-11-11 (Wednesday). Loaded once into EDITORIAL_REVIEW; an editor approves before anything is published.
-- Facts restated in Boston Daily's own words with attribution. Every story carries its own photo; none was used in an earlier package or in the open 2026-11-09 and 2026-11-10 drafts (grepped content/ and seed/).
-- Wikimedia Commons and loc.gov were unreachable from the newsroom sandbox on this run. Photo URLs are original-file Commons URLs built from file names found in web search (MD5 path); all are U.S. government or Library of Congress public-domain photos. Editor: confirm each photo loads and matches its caption; the image check removes any that do not.
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261111-hegseth-impeachment-shelved', 'house-shelves-massie-hegseth-impeachment-211-204-judiciary-committee', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'House shelves Massie''s impeachment articles against Hegseth on a 211-204 vote', 'The vote on Tuesday, Nov. 10, sent the resolution to the Judiciary Committee, effectively ending it in the current Congress. Massie was the only Republican to oppose the move.', 'The House voted 211-204 on Tuesday, Nov. 10, to send Rep. Thomas Massie''s resolution to impeach Defense Secretary Pete Hegseth to the House Judiciary Committee, ABC News and Fox News reported. The procedural vote headed off a possible impeachment vote on Wednesday, Nov. 11, and effectively kills the measure for the rest of the Republican-controlled 119th Congress, according to ABC News.

## How the vote broke

Massie, R-Ky., was the only Republican to vote against referring the resolution, and Democrats voted against it as well, ABC News reported. Fox News reported that GOP leaders had worried that absences after the party''s midterm losses could change the outcome.

## The articles

Massie introduced eight articles of impeachment on the House floor on Monday, Nov. 9. They focus on military operations that Congress did not approve, including the Iran war and strikes on boats suspected of carrying drugs, ABC News reported. Massie lost his primary earlier this year to a challenger backed by President Trump.

## Reactions

Hegseth called the effort a "political spectacle" driven by "ego and resentment," and said the operations were lawful and directed by the president, according to ABC News and Fox News. Speaker Mike Johnson had opposed the articles. President Trump wrote that Democrats had "FAILED," although a Republican led the effort, and Pentagon spokesman Sean Parnell posted "TOTAL VICTORY," ABC News reported. Secretary of State Marco Rubio said Hegseth had carried out orders from the commander in chief.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/b/bf/Flickr_-_USCapitol_-_The_United_States_Capitol_Dome.jpg', 'The U.S. Capitol dome, Washington (file). Photo: Architect of the Capitol via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-11.sql', 9, 1, 'newsroom-assistant', '2026-11-11T10:45:00.000Z', '2026-11-11T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261111-hegseth-impeachment-shelved-src1', 'bd-20261111-hegseth-impeachment-shelved', 'House tables Hegseth impeachment, effectively killing it in current Congress', 'https://abcnews.com/US/hegseth-dismisses-impeachment-effort-political-spectacle/story?id=138002466', 'ABC News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-11T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-11. Editor to confirm.', 'newsroom-assistant', '2026-11-11T10:45:00.000Z');
