INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261111-gop-leadership', 'jim-jordan-beats-scalise-house-minority-leader-senate-republicans-keep-thune', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Jim Jordan beats Steve Scalise 106-73 to lead House Republicans in the minority, and Senate Republicans keep John Thune', 'The leadership votes on Tuesday, Nov. 10, pick the Republicans who will face Democratic majorities in both chambers when the new Congress meets in January.', 'House Republicans chose Rep. Jim Jordan of Ohio as their leader for the 120th Congress on Tuesday, Nov. 10, electing him minority leader over Majority Leader Steve Scalise of Louisiana by 106 votes to 73 in a closed-door secret ballot, ABC News and Scripps station ABC15 reported.

## The House

Jordan chairs the House Judiciary Committee and is not expected to keep that job in the new Congress, ABC15 reported. He and Scalise both ran for speaker after Kevin McCarthy was removed in 2023, and neither won enough support before Mike Johnson got the job. Johnson, who said he would not lead the conference in the minority, remains speaker until the new Congress convenes in January, according to CBS News and ABC15. Before the vote, CBS News reported that Rep. August Pfluger of Texas was challenging Majority Whip Tom Emmer for the No. 2 post.

## The Senate

Senate Republicans re-elected Majority Leader John Thune of South Dakota as their leader by voice vote, Roll Call reported. He ran unopposed. Five Republican senators led by Ron Johnson of Wisconsin had pushed to delay the elections, which moved them back by a few hours but not to another day. "This has never been anything against John Thune," Johnson said, according to Roll Call.

The conference also re-elected John Barrasso of Wyoming as whip, Tom Cotton of Arkansas as conference chairman, James Lankford of Oklahoma as vice chair and Shelley Moore Capito of West Virginia as policy committee chair. Bernie Moreno of Ohio will lead the National Republican Senatorial Committee. Sen. Rand Paul of Kentucky said voters were reacting to gas prices, the Iran war and the cost of living, not to how the conference was run, Roll Call reported.

Democrats won both chambers in the Nov. 3 midterms and were on pace for at least 256 House seats and at least 54 Senate seats, CBS News reported.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/2/2c/Aerial_view_from_above_the_U.S._Capitol_17223v.jpg', 'Aerial view from above the U.S. Capitol, Washington (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-11.sql', 8, 0, 'newsroom-assistant', '2026-11-11T10:45:00.000Z', '2026-11-11T10:45:00.000Z');
