INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261111-senate-counts', 'peltola-lead-grows-alaska-senate-count-mississippi-ballot-deadline-passes-colom-ahead', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Peltola stretches her Alaska Senate lead after another large count, and Mississippi''s ballot deadline passes with Colom ahead', 'Alaska plans its ranked-choice tabulation for Wednesday, Nov. 18. Mississippi counties have until Friday, Nov. 13, to certify.', 'Democrat Mary Peltola widened her lead over Republican Sen. Dan Sullivan in Alaska''s Senate race on Tuesday, Nov. 10, as election officials counted more than 24,000 additional votes, Alaska Public Media reported. After that update, Peltola had 49% of first-choice votes to Sullivan''s 47.2%, with the Associated Press estimating that 84% of the vote had been counted.

## Alaska

Earlier on Tuesday, before the new batch, Peltola led by 2,517 votes, 106,321 to 103,804, Fox News reported. Her lead had stood at 637 votes for days after the Nov. 3 election. Her campaign said she won Monday''s batch of ballots 68% to 30%.

The Division of Elections plans to release more results on Friday, Nov. 13. The ranked-choice tabulation is set for Wednesday, Nov. 18, and certification for Wednesday, Nov. 25, according to Fox News. In other races, Democrat Jonathan Kreiss-Tomkins had 49.9% of first-choice votes for governor, and Rep. Nick Begich, a Republican, led independent Bill Hill 48.9% to 41% for the U.S. House, Alaska Public Media reported. Ballot Measure 2, which would repeal ranked-choice voting, was failing 53% to 47%.

## Mississippi

Democrat Scott Colom led Republican Sen. Cindy Hyde-Smith 467,961 votes (49.1%) to 465,425 (48.8%), a margin of 2,536, WLBT reported on the morning of Tuesday, Nov. 10. That day was the deadline for mail ballots postmarked by Election Day to arrive and for affidavit voters to cure their ballots. Counties must finish counting and certify by Friday, Nov. 13.

As of Monday, Nov. 9, counties were waiting on 2,578 mail ballots, and 76% of the 15,547 affidavit ballots processed so far had been accepted, WLBT reported, citing Secretary of State Michael Watson. Mississippi has no automatic recount, so any challenge would likely go to court, Newsweek reported. Hyde-Smith''s lawyers have asked all 82 counties to keep affidavit ballots separate, and Colom''s campaign argued that no law requires it and warned it could threaten ballot secrecy.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/1/1f/DELTA_JUNCTION,_VIEW_NORTH._THIS_SMALL_TOWN_LIES_AT_THE_MAIN_HIGHWAY_INTERSECTION_OF_THE_ALASKA_HIGHWAY_(THE_ALCAN)..._-_NARA_-_550584.jpg', 'Delta Junction, Alaska, at the junction of the Alaska Highway, 1970s (file). Photo: EPA DOCUMERICA / U.S. National Archives via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-11.sql', 8, 0, 'newsroom-assistant', '2026-11-11T10:45:00.000Z', '2026-11-11T10:45:00.000Z');
