INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261111-trump-questions-midterms-ev1', 'bd-20261111-trump-questions-midterms', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-11T10:45:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261111-scotus-agency-fines', 'supreme-court-sun-valley-orchards-labor-department-fines-jury-trial-argument', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Supreme Court weighs whether the Labor Department can fine a New Jersey farm without a jury', 'Justices across the court pressed both sides at the argument on Tuesday, Nov. 10, over a penalty of about $500,000. The answer could change how many federal agencies enforce the law.', 'The Supreme Court heard arguments on Tuesday, Nov. 10, in *Department of Labor v. Sun Valley Orchards*, a case over whether a federal agency can impose fines through its own in-house proceedings, NPR reported via KPBS. The justices appeared divided.

## The case

The Labor Department fined Sun Valley Orchards, a New Jersey farm, about $500,000 over what it said were unsanitary conditions, unsafe drinking water, overcrowded housing and unpaid wages for workers hired through a federal seasonal farmworker visa program, NPR reported. Sun Valley disputes the findings. It argues that making it fight the penalty before an administrative law judge, with only limited review by a federal court later, violates its right to a jury trial under Article III of the Constitution. The U.S. Court of Appeals for the Third Circuit agreed with the farm, SCOTUSblog reported.

The dispute builds on the court''s 2024 decision in *SEC v. Jarkesy*, which separated "public rights" that agencies may decide from private claims that generally belong in court, according to SCOTUSblog. The justices also added a question about whether the department had legal authority to impose the penalties at all.

## At the argument

Chief Justice John Roberts suggested the executive branch, under this and past administrations, may have gone beyond its power, NPR reported. Justice Elena Kagan asked why the government should not always have to go to court. Justice Ketanji Brown Jackson said Congress meant to protect domestic workers from being undercut, and Justice Brett Kavanaugh said the farm''s approach was "at war with clarity."

Deputy Solicitor General Sarah Harris warned that requiring every civil penalty to go through federal court would be "the nuclear option," with possible effects on Medicare, Medicaid and federal student loan programs.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/5/5c/Flickr_-_USCapitol_-_Old_Supreme_Court_Chamber.jpg', 'The Old Supreme Court Chamber in the U.S. Capitol, Washington (file). Photo: Architect of the Capitol via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-11.sql', 7, 0, 'newsroom-assistant', '2026-11-11T10:45:00.000Z', '2026-11-11T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261111-scotus-agency-fines-src1', 'bd-20261111-scotus-agency-fines', 'Supreme Court seems split over federal agencies'' ability to fine for law violations', 'https://www.kpbs.org/news/politics/2026/11/10/supreme-court-seems-split-over-federal-agencies-ability-to-fine-for-law-violations', 'NPR via KPBS', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-11T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-11. Editor to confirm.', 'newsroom-assistant', '2026-11-11T10:45:00.000Z');
