INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261111-scotus-agency-fines-ev1', 'bd-20261111-scotus-agency-fines', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-11T10:45:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261111-celtics-76ers', 'celtics-beat-76ers-123-101-paul-george-36-points-boston-9-2-atlantic-lead', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Celtics 123, 76ers 101: Paul George scores 36 as Boston pulls away in Philadelphia and takes the Atlantic lead', 'The Celtics outscored the 76ers 32-19 in the fourth quarter on Tuesday, Nov. 10, and improved to 9-2.', 'Paul George scored 36 points and the Boston Celtics beat the Philadelphia 76ers 123-101 at Xfinity Mobile Arena on Tuesday, Nov. 10, ESPN and VAVEL reported. Boston improved to 9-2 and moved half a game ahead of Philadelphia (9-3) for first place in the Atlantic Division.

George made 14 of 22 shots, including 6 of 11 three-pointers, according to VAVEL. Jayson Tatum added 21 points, six rebounds, four assists and two blocks, Payton Pritchard had 18 points, six rebounds and five assists, and Sam Hauser scored 12.

## How it got away

Boston led 30-23 after one quarter and 62-51 at halftime. Philadelphia won the third quarter 31-29 to trail 91-82, but the Celtics closed the game on a 32-19 fourth quarter, ESPN reported. Boston shot 51% from the field and made 22 of 49 threes (45%). Philadelphia shot 42% and made 11 of 37 from deep.

## Philadelphia

Tyrese Maxey led the 76ers with 24 points on 8-of-12 shooting, and Joel Embiid had 16 points and six rebounds, VAVEL reported. Philadelphia was without centers Adem Bona and Ariel Hukporti and forward Dominick Barlow. The 76ers committed 14 turnovers to Boston''s nine, according to ESPN.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/5/54/PA_Convention_Center_1993_Highsmith.jpg', 'The Pennsylvania Convention Center, Philadelphia, 1993 (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-11.sql', 6, 0, 'newsroom-assistant', '2026-11-11T10:45:00.000Z', '2026-11-11T10:45:00.000Z');
